import { useState } from 'react';

type Props = { submitPayment: () => Promise<void> };

export default function Checkout({ submitPayment }: Props) {
  const [status, setStatus] = useState('Ready');

  async function pay() {
    setStatus('Sending');
    await submitPayment();
    setStatus('Paid');
  }

  return (
    <section>
      <p role="status">{status}</p>
      <button onClick={pay}>Pay</button>
    </section>
  );
}

let totalDebited = 0;
let nextReceiptId = 1;

function charge(orderId, amount) {
  totalDebited += amount;
  return { receiptId: nextReceiptId++, orderId, amount };
}

function getTotalDebited() {
  return totalDebited;
}

module.exports = { charge, getTotalDebited };
